"""Static guards for the Capability roster (能力名冊) in python/cinbase/capabilities.py.

The roster replaced three inline ``imeDirName`` capability tuples in the shared
cinbase engine: one declaration of which Service may use Intelligent select
(智慧選字), read at every seam instead of copied per call site. These tests pin
the before/after consequence of that move:

* the rostered set and the per-Service ``has()`` answers,
* the 功能開關 menu golden tables transcribed from the engine before the move,
* no inline capability tuple and no dead ``CinBase.imeNameList`` left in the engine,
* every Service configuration package agreeing with the roster about Intelligent select,
* the settings-UI allow-list in config.js being the same roster, so JS and Python cannot drift.

Pure static analysis: the roster module is loaded by file path, and the engine,
the settings UI and the configuration packages are read as text or JSON. No
Service instantiation, no Win32 shim, no line protocol.
"""

import importlib.util
import json
import os
import re
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
CINBASE_DIR = os.path.join(ROOT, "python", "cinbase")
ENGINE_PATH = os.path.join(CINBASE_DIR, "__init__.py")
CONFIG_JS_PATH = os.path.join(CINBASE_DIR, "config", "js", "config.js")
INPUT_METHODS_DIR = os.path.join(ROOT, "python", "input_methods")

# Directory names under python/input_methods/ that the discovery rule below
# excludes and that must therefore never be rostered. `meow`, `rime`,
# `chewing` and `braille_chewing` are not cinbase Services: they never load
# python/cinbase (standalone backends or native bindings) and carry no cinbase
# config/config.json package. `cheeng` is the English-mode TextService helper:
# it is cinbase-adjacent but has no config/config.json either, so it is not a
# rosterside Service and cannot enable Intelligent select from a package.
NON_CINBASE_SERVICES = ("meow", "rime", "chewing", "braille_chewing")
CONFIG_LESS_SERVICES = ("cheeng",)

# Golden tables, transcribed literally from python/cinbase/__init__.py at the
# pre-refactor tree: the rostered 功能開關 menu (then :741) and the un-rostered
# one (then :744). Moving the roster must neither lose a member nor reorder it.
GOLDEN_ROSTERED_MENU = [
    "fullShapeSymbols",
    "easySymbolsWithShift",
    "autoClearCompositionChar",
    "playSoundWhenNonCand",
    "showPhrase",
    "sortByPhrase",
    "intelligentSelect",
    "intelligentSelectRecent",
    "intelligentSelectContext",
    "supportWildcard",
    "imeReverseLookup",
    "homophoneQuery",
]
GOLDEN_COMMON_MENU = [
    "fullShapeSymbols",
    "easySymbolsWithShift",
    "autoClearCompositionChar",
    "playSoundWhenNonCand",
    "showPhrase",
    "sortByPhrase",
    "supportWildcard",
    "imeReverseLookup",
    "homophoneQuery",
]

# Any `"chedayi", "chebihua"`-style inline tuple, in either order, either quote
# style and any spacing: the form the three engine sites used before the roster.
INLINE_TUPLE = re.compile(r"""["'](chedayi|chebihua)["']\s*,\s*["'](chebihua|chedayi)["']""")

# The settings-UI hide gate: an allow-list array tested against imeFolderName.
GATE = re.compile(
    r"if\s*\(\s*\[(?P<list>[^\]]*)\]\.indexOf\(\s*imeFolderName\s*\)\s*===\s*-1\s*\)"
)

# The settings-UI seed gate: ``imeFolderName == "<name>" && typeof
# checjConfig.<key> === "undefined"``. This is the second copy of the roster
# decision in the same script, and the array-form guard above cannot see it —
# which is how the two drifted apart. The keys are in fact always present in the
# served /config payload (python/cinbase/config.py sets all three in
# ``CinBaseConfig.__init__`` and ``load()`` only ever ``__dict__.update()``s, so
# ``toJson()`` can never omit them), making the branch unreachable today; what it
# must never do is seed Intelligent select for a Service the roster denies it.
SEED_GATE = re.compile(
    r'imeFolderName\s*==\s*"(?P<name>[a-z]+)"\s*&&\s*typeof\s+checjConfig\.'
    r'(?P<key>intelligentSelect\w*)\s*===\s*"undefined"'
)

MENU_ITEMS_LITERAL = re.compile(r"cbTS\.smenuitems\s*=\s*\[([^\]]*)\]")
QUOTED_NAME = re.compile(r'"([^"]+)"')
HAS_CALL = re.compile(
    r"capabilities\.has\(\s*cbTS\.imeDirName\s*,\s*capabilities\.INTELLIGENT_SELECT\s*\)"
)
HAS_MENU_ITEMS_CALL = re.compile(
    r"capabilities\.has_menu_items\(\s*cbTS\.imeDirName\s*\)"
)


def load_capabilities_module():
    """Load python/cinbase/capabilities.py without importing the cinbase package."""
    spec = importlib.util.spec_from_file_location(
        "cinbase_capabilities_under_test",
        os.path.join(CINBASE_DIR, "capabilities.py"),
    )
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


capabilities = load_capabilities_module()


def read_text(path):
    with open(path, encoding="utf-8") as source:
        return source.read()


def cinbase_service_names():
    """The Service directory names under python/input_methods/ that carry a
    cinbase config/config.json package — the rosterside inventory."""
    return {
        entry
        for entry in os.listdir(INPUT_METHODS_DIR)
        if os.path.isfile(os.path.join(INPUT_METHODS_DIR, entry, "config", "config.json"))
    }


class CapabilityRosterTests(unittest.TestCase):
    def test_roster_membership_and_has_agrees_per_service(self):
        """The roster is exactly the two dayi-family Services, and has() answers
        for every discovered cinbase Service and every excluded directory."""
        self.assertEqual(set(capabilities.CAPABILITIES), {"chedayi", "chebihua"})
        # Pin the interface directly, not only through has(): the rostered
        # names and an un-rostered one answer straight from the roster data.
        self.assertEqual(capabilities.capabilities_for("chedayi"),
                         frozenset({capabilities.INTELLIGENT_SELECT}))
        self.assertEqual(capabilities.capabilities_for("chebihua"),
                         frozenset({capabilities.INTELLIGENT_SELECT}))
        self.assertEqual(capabilities.capabilities_for("checj"), frozenset())
        self.assertIs(capabilities.has("chedayi", capabilities.INTELLIGENT_SELECT), True)
        self.assertIs(capabilities.has("checj", capabilities.INTELLIGENT_SELECT), False)
        services = cinbase_service_names()
        self.assertTrue({"chedayi", "chebihua"} <= services,
                        "the rostered Services must carry a config/config.json")
        for name in sorted(services):
            rostered = name in capabilities.CAPABILITIES
            with self.subTest(service=name):
                self.assertIs(
                    capabilities.has(name, capabilities.INTELLIGENT_SELECT), rostered)
                expected = (frozenset({capabilities.INTELLIGENT_SELECT})
                            if rostered else frozenset())
                self.assertEqual(capabilities.capabilities_for(name), expected)
        for name in NON_CINBASE_SERVICES + CONFIG_LESS_SERVICES:
            self.assertNotIn(name, services,
                             f"{name} must stay outside the discovery rule")
            self.assertIs(capabilities.has(name, capabilities.INTELLIGENT_SELECT), False)
            self.assertEqual(capabilities.capabilities_for(name), frozenset())

    def test_menus_are_the_golden_tables_built_from_menu_items(self):
        """The rostered menu equals the transcribed 12-name golden table and is
        assembled from capabilities.MENU_ITEMS; the un-rostered menu is still
        the engine's literal 9-name golden table."""
        self.assertEqual(list(capabilities.MENU_ITEMS), [capabilities.INTELLIGENT_SELECT])
        self.assertEqual(
            list(capabilities.MENU_ITEMS[capabilities.INTELLIGENT_SELECT]),
            ["intelligentSelect", "intelligentSelectRecent", "intelligentSelectContext"])
        # The shared common-items list is the golden 9 itself: drift in
        # COMMON_MENU_ITEMS fails the gate, not just the derived menus.
        self.assertEqual(tuple(capabilities.COMMON_MENU_ITEMS),
                         tuple(GOLDEN_COMMON_MENU))
        for name in sorted(capabilities.CAPABILITIES):
            with self.subTest(service=name):
                self.assertEqual(list(capabilities.menu_items_for(name)),
                                 GOLDEN_ROSTERED_MENU)
        # The rostered menu is the common items with the capability's own items
        # spliced in after sortByPhrase — the exact position the golden table shows.
        anchor = GOLDEN_COMMON_MENU.index("sortByPhrase") + 1
        self.assertEqual(
            GOLDEN_ROSTERED_MENU,
            GOLDEN_COMMON_MENU[:anchor]
            + list(capabilities.MENU_ITEMS[capabilities.INTELLIGENT_SELECT])
            + GOLDEN_COMMON_MENU[anchor:])

        engine = read_text(ENGINE_PATH)
        # The engine builds the rostered menu through the roster interface...
        self.assertEqual(
            len(HAS_MENU_ITEMS_CALL.findall(engine)), 1,
            "the 功能開關 roster branch must ask the roster whether the Service has menu items")
        self.assertIn(
            "cbTS.smenuitems = list(capabilities.menu_items_for(cbTS.imeDirName))",
            engine,
            "the rostered smenuitems must be derived from the roster, not recopied")
        # ...while chephonetic, cheez and the un-rostered else branch keep their
        # literal menus; the last literal is the else branch and must be the golden 9.
        literals = MENU_ITEMS_LITERAL.findall(engine)
        self.assertEqual(len(literals), 3,
                         "only chephonetic, cheez and the else branch keep literal menus")
        self.assertEqual(QUOTED_NAME.findall(literals[-1]), GOLDEN_COMMON_MENU)
        for name in sorted(set(cinbase_service_names()) - set(capabilities.CAPABILITIES)):
            self.assertIs(capabilities.has_menu_items(name), False,
                          f"un-rostered {name} must reach the else branch")

    def test_no_inline_capability_tuple_survives_in_the_engine(self):
        """None of the three sites may still carry the inline tuple, and the two
        Intelligent-select sites must read the roster instead."""
        engine = read_text(ENGINE_PATH)
        residual = INLINE_TUPLE.search(engine)
        self.assertIsNone(
            residual,
            "python/cinbase/__init__.py still carries an inline capability tuple")
        self.assertEqual(
            len(HAS_CALL.findall(engine)), 2,
            "sortByIntelligentSelect and addIntelligentSelectCount must both read capabilities.has()")

    def test_config_packages_enabling_intelligent_select_are_exactly_the_roster(self):
        """A Service's configuration package may only enable Intelligent select
        when the roster holds it — the invariant that keeps config and roster
        from diverging and makes the lying default in cinbase/config.py harmless."""
        enabled = set()
        for name in sorted(cinbase_service_names()):
            config_path = os.path.join(INPUT_METHODS_DIR, name, "config", "config.json")
            with open(config_path, encoding="utf-8") as config_file:
                config = json.load(config_file)
            if config.get("intelligentSelect", False) is True:
                enabled.add(name)
        self.assertEqual(enabled, set(capabilities.CAPABILITIES))

    def test_settings_ui_gate_reads_the_same_roster(self):
        """The config.js allow-list hiding #dayiSmartSelectionOptions equals the
        roster, so the settings UI and the Python roster cannot drift."""
        js = read_text(CONFIG_JS_PATH)
        gate = GATE.search(js)
        self.assertIsNotNone(
            gate,
            "config.js must gate the 智慧選字 block on a roster allow-list")
        self.assertIn("#dayiSmartSelectionOptions", js[gate.start():gate.start() + 300],
                      "the allow-list gate must be the one hiding #dayiSmartSelectionOptions")
        allowed = QUOTED_NAME.findall(gate.group("list"))
        self.assertEqual(len(allowed), len(set(allowed)),
                         "the settings-UI allow-list must not repeat a Service")
        self.assertEqual(set(allowed), set(capabilities.CAPABILITIES))

    def test_settings_ui_seed_gate_names_only_rostered_services(self):
        """The second roster copy in config.js — the undefined-seed gate — may
        name only rostered Services, and must seed every Intelligent-select key
        the engine reads."""
        js = read_text(CONFIG_JS_PATH)
        seeds = SEED_GATE.findall(js)
        self.assertEqual(
            {key for _, key in seeds},
            {"intelligentSelect", "intelligentSelectRecent", "intelligentSelectContext"},
            "every Intelligent-select key the engine reads must have its seed gate")
        named = {name for name, _ in seeds}
        self.assertTrue(
            named <= set(capabilities.CAPABILITIES),
            "the seed gate names %s, outside the Capability roster %s"
            % (sorted(named), sorted(capabilities.CAPABILITIES)))

    def test_dead_ime_name_list_is_gone(self):
        """The dead CinBase.imeNameList must not come back: CinDict in
        configtool.py and this Capability roster are the rosters that bite."""
        self.assertNotIn("imeNameList", read_text(ENGINE_PATH))


if __name__ == "__main__":
    unittest.main()
